// Isolated design prototype. No daemon API, storage writes, or runtime imports.
const concepts = [
  {name:'По этапам',sub:'Сначала понять процесс',title:'От задачи до проверенного результата',description:'Навигация повторяет ход работы. Сначала — что сделать, затем — как выполнить, после — что получилось.',hypothesis:'Человек без знания терминов burnex найдёт следующий шаг и отличит сценарий от его прогона.',audience:'Первое знакомство и регулярная работа с разработкой.',benefit:'Пять понятных разделов вместо списка технических экранов. Решения человека находятся рядом с результатом работы.',risk:'Опытному оператору потребуется дополнительный переход к настройкам. Поэтому текущие прогоны и ожидания остаются видны на обзоре.',route:'Планировать → Очередь → Выбрать сценарий → Прогон → Проверить',backend:'Группировка меню и вкладок на клиенте. Backlog и Scrum — два вида одной очереди. Существующие адреса и динамические вклады расширений сохраняются.',test:'Попросить нового пользователя найти очередь, запустить выбранную задачу и объяснить разницу между сценарием и прогоном.'},
  {name:'Центр внимания',sub:'Сначала понять, что делать',title:'Burnex работает. Где нужен человек?',description:'Главный экран — очередь вмешательств: решения, предложения изменений и остановившиеся прогоны.',hypothesis:'Пользователь быстрее поймёт, что требует его участия, а что движок выполняет самостоятельно.',audience:'Оператор нескольких параллельных прогонов.',benefit:'Причина, контекст и доступные действия находятся в одном месте. Ожидание ответа отделено от ошибки.',risk:'При пустой очереди внимания продукт кажется пустым. Нужны постоянные входы в задачи, сценарии и все прогоны.',route:'Требует внимания → Причина → Контекст прогона → Действие',backend:'Сводка overview.awaiting, proposals и статусов на клиенте. Никаких новых уведомлений или правил приоритета на сервере.',test:'Попросить найти прогон, ожидающий ответа, и отличить его от прогона с ошибкой; не подсказывать название раздела.'},
  {name:'Вокруг задачи',sub:'Сначала понять контекст',title:'Одна задача — всё, что с ней происходит',description:'Очередь становится рабочим пространством. Из карточки доступны исполнитель, связанный прогон и его результат.',hypothesis:'Пользователь не теряет исходную цель, переходя между очередью, журналом и проверкой результата.',audience:'Разработчик или руководитель, работающий из очереди задач.',benefit:'Технический прогресс привязан к человеческому намерению. Список и доска — представления одной сущности.',risk:'Не каждый прогон связан с задачей. Нужен самостоятельный раздел всех прогонов; связь нельзя угадывать по названию.',route:'Очередь → Карточка задачи → Связанный прогон → Проверка',backend:'Использовать только явные связи владельца/запуска, уже доступные из данных. При отсутствии связи — «Прогон не связан» и общий список. Полная история задачи может потребовать backend и в этот этап не входит.',test:'Попросить объяснить, кто выполняет конкретную задачу, на каком она этапе и как посмотреть результат.'},
  {name:'Вокруг сценария',sub:'Сначала выбрать способ',title:'Выберите работу, которую поручите burnex',description:'Сценарий описывает способ выполнения, а прогоны показывают попытки. Они собраны в одном пространстве.',hypothesis:'Пользователь быстрее увидит возможности движка и перестанет путать пайплайн с конкретным запуском.',audience:'Автор автоматизаций и пользователь повторяемых процессов.',benefit:'Описание результата, граф, агент, расписание и история располагаются вокруг сценария. Запуск становится контекстным.',risk:'Задачи и вмешательства могут затеряться. Для них остаются отдельные постоянные вкладки.',route:'Каталог сценариев → Состав и параметры → Запуск → История',backend:'Связь прогонов с пайплайном уже есть в grouping.ts: projectKey + pipelineFile. Описания — поясняющий текст UI; редактирование YAML и расписания не добавляется.',test:'Попросить выбрать сценарий для задачи, найти его последние прогоны и объяснить, что произойдёт после запуска.'},
  {name:'Карта возможностей',sub:'Сначала увидеть целое',title:'Что можно делать с burnex?',description:'Главная — понятная карта продукта. Входы сформулированы через намерения, технические термины объясняются рядом.',hypothesis:'Пользователь обнаружит больше существующих возможностей и сам выберет подходящий путь.',audience:'Новый пользователь и редкие возвращения в продукт.',benefit:'Видна вся система: планирование, исполнение, контроль, агенты и расширения. Ни один экран не становится скрытой функцией.',risk:'Карта требует чтения и занимает место. Для ежедневной работы нужны прямые входы в активные прогоны и ожидания.',route:'Намерение → Раздел → Объект → Действие',backend:'Новая главная и клиентские ссылки на существующие цели маршрутов. Не требует новых сущностей, поиска по серверу или API.',test:'Попросить найти выбор модели, стоимость работы и предложенные агентом изменения, не называя разделы интерфейса.'},
];
const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge = (text, color='') => `<span class="badge ${color}">${text}</span>`;
const button = (label, action, value='', cls='') => `<button class="${cls}" data-action="${action}" data-value="${value}">${label}</button>`;
const names = {overview:'Обзор работы',plan:'Планировать',execute:'Выполнять',review:'Проверить',settings:'Настроить',attention:'Требует внимания',runs:'Все прогоны',tasks:'Задачи',scenarios:'Сценарии',catalog:'Каталог сценариев',schedule:'Расписание',usage:'Расходы',map:'Карта возможностей',extensions:'Расширения'};
let variant = Math.min(5, Math.max(1, Number(location.hash.slice(1)) || 1));
let section = 'home';
let activeAttention = 'decision';
let taskView = 'board';
let query = '';
let toastTimeout;
const initialSections = ['overview','attention','tasks','catalog','map'];
const tasks = [
  {id:'BX-42',title:'Понятная навигация витрины',status:'В очереди',column:0,description:'Объединить список и доску в раздел «Задачи».',meta:'Готова к запуску',color:'',run:false},
  {id:'BX-43',title:'Проверить обработку ошибок',status:'В очереди',column:0,description:'Проверить сообщение при недоступном бэкенде.',meta:'После BX-41',color:'',run:false},
  {id:'BX-41',title:'Добавить фильтры прогонов',status:'В работе',column:1,description:'Агент выполняет шаг implement.',meta:'self-improve · #a31f',color:'green',run:true},
  {id:'BX-39',title:'Уточнить сообщения в UI',status:'Готово',column:2,description:'Проверки пройдены. Прогон завершён.',meta:'self-improve · #9c2e',color:'green',run:true},
];
const runs = [
  {name:'Добавить фильтры прогонов',scenario:'self-improve',id:'#a31f',status:'Выполняется',color:'green',detail:'implement · 12 мин · $0.84'},
  {name:'Проверить результат изменений',scenario:'review-change',id:'#b72a',status:'Ждёт ответа',color:'orange',detail:'review / decision · 8 мин ожидания'},
  {name:'Исправить тесты',scenario:'fix-tests',id:'#c28b',status:'Ошибка',color:'red',detail:'verify / tests · код выхода 1'},
];
const scenarios = [
  {id:'self-improve',icon:'↻',name:'Развивать проект',text:'Взять задачу из очереди, реализовать, проверить и подготовить результат.',meta:'Очередь → реализация → ревью',featured:true},
  {id:'fix-tests',icon:'✓',name:'Исправить тесты',text:'Найти причину падения, исправить код и повторить проверки.',meta:'Исправление → проверка'},
  {id:'review-change',icon:'◇',name:'Проверить изменения',text:'Разобрать изменения и остановиться на шаге решения человека.',meta:'Ревью → решение'},
];
function appTop(){return `<div class="app-top"><div class="app-top-left"><span class="app-logo">burnex<span> /</span></span><span class="divider"></span><span class="project-pill">Проект: burnex</span><span class="mock-label">ДЕМО</span></div><div class="app-top-right">${button('Нужен ответ · 1','navigate','attention','accent')}${button('+ Новый прогон','launch','','primary')}</div></div>`;}
function sideNav(items,caption){return `<aside class="sidebar"><span class="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО</span><nav aria-label="Разделы макета">${items.map(([key,icon])=>`<button class="nav-button ${section===key?'active':''}" data-action="navigate" data-value="${key}" ${section===key?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${names[key]}${key==='review'?'<span class="nav-count">2</span>':''}</button>`).join('')}</nav><p class="nav-caption">${caption}</p><div class="side-bottom"><span class="eyebrow">ПОД КАПОТОМ</span>${button('Агенты и модели','navigate','settings','nav-button')}${button('Расширения','navigate','extensions','nav-button')}<p class="nav-caption">Сценарий — план работы.<br>Прогон — его выполнение.</p></div></aside>`;}
function topNav(items){return `<nav class="top-nav" aria-label="Разделы макета">${items.map(key=>button(names[key], 'navigate',key,section===key?'active':'')).join('')}</nav>`;}
function heading(title,desc,action=''){return `<div class="page-head"><div><h2>${title}</h2><p>${desc}</p></div>${action}</div>`;}
function metrics(){return `<div class="metrics">${[['Выполняется','1','Прогон работает'],['Нужен ответ','1','Решение человека'],['Предложения','1','Изменения конфигурации'],['Расход сегодня','$2.48','Демонстрационная оценка']].map(([label,n,sub])=>`<div class="metric"><span>${label}</span><strong>${n}</strong><small>${sub}</small></div>`).join('')}</div>`;}
function runRows(){return `<div class="panel">${runs.map((r,i)=>`<button class="task-row" data-action="run" data-value="${i}"><span class="status-dot ${r.color}"></span><span class="row-body"><strong>${r.name}</strong><p>${r.scenario} · ${r.id} · ${r.detail}</p></span>${badge(r.status,r.color)}<span class="arrow">↗</span></button>`).join('')}</div>`;}
function overview(){return `${heading('Работа под контролем','Планируйте задачи. Поручайте выполнение. Проверяйте результат.')}${metrics()}<div class="callout"><span>◇</span><div><strong>Один прогон ждёт вашего решения</strong><p>review-change остановился на шаге проверки результата.</p></div>${button('Посмотреть','navigate','review')}</div><div class="two-col"><div><div class="section-title"><h3>Что происходит сейчас</h3>${button('Все прогоны →','navigate','runs','text-button')}</div>${runRows()}<div class="section-title"><h3>Следующая задача</h3></div><div class="panel"><button class="task-row" data-action="task" data-value="BX-42"><span class="row-body"><strong>Понятная навигация витрины</strong><p>Готова к работе · ещё не запускалась</p></span><span class="arrow">→</span></button></div></div><div class="panel panel-pad"><span class="eyebrow">КАК УСТРОЕНА РАБОТА</span>${[['1','Запланировать','Добавьте задачу в очередь.'],['2','Выбрать сценарий','Определите, как её выполнить.'],['3','Наблюдать за прогоном','Смотрите шаги, логи и расход.'],['4','Проверить результат','Ответьте там, где нужен человек.']].map(([n,t,d])=>`<div class="guide"><span class="circle">${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div>`;}
function taskCard(t){return `<button class="board-card" data-action="task" data-value="${t.id}"><span class="mono muted">${t.id}</span><h3>${t.title}</h3><p>${t.description}</p>${t.column===1?'<div class="progress"><span style="width:55%"></span></div>':''}<div class="card-footer"><span class="small muted">${t.meta}</span><span class="arrow">↗</span></div></button>`;}
function tasksContent(){const filtered = tasks.filter(t=>(t.title+' '+t.id).toLowerCase().includes(query.toLowerCase()));return `${heading('Задачи проекта','Одна очередь. Два способа видеть работу.',button('+ Добавить задачу','addtask'))}<div class="toolbar"><input class="search" id="task-search" aria-label="Найти задачу" placeholder="Найти задачу…" value="${escapeHtml(query)}"><div class="view-switch" aria-label="Вид очереди">${button('Доска','taskview','board',taskView==='board'?'active':'')}${button('Список','taskview','list',taskView==='list'?'active':'')}</div></div><div id="task-results">${taskResults(filtered)}</div><p class="inline-note">«В работе» означает, что задачу взял прогон. Простое перемещение карточки не заменяет запуск сценария.</p>`;}
function taskResults(filtered){return taskView==='board'?`<div class="board">${['В очереди','В работе','Готово'].map((name,i)=>`<section class="board-column"><div class="column-title"><span>${name}</span><span class="muted">${filtered.filter(t=>t.column===i).length}</span></div>${filtered.filter(t=>t.column===i).map(taskCard).join('')||'<p class="empty">Нет задач</p>'}</section>`).join('')}</div>`:`<div class="panel">${filtered.map(t=>`<button class="task-row" data-action="task" data-value="${t.id}"><span class="mono muted">${t.id}</span><span class="row-body"><strong>${t.title}</strong><p>${t.meta}</p></span>${badge(t.status,t.color)}<span class="arrow">↗</span></button>`).join('')||'<p class="empty">Ничего не найдено</p>'}</div>`;}
function inbox(){return `${heading('Где нужен ваш ответ','Движок выполняет работу сам. Здесь — места, где он не может продолжить без вас.')}<div class="inbox-grid"><div class="inbox-list">${[['decision','Решение человека','Проверить результат изменений','review-change · #b72a','8 мин назад','orange'],['proposal','Предложение агента','Изменение конфигурации','self-improve · .burnex/','12 мин назад','orange'],['failure','Ошибка прогона','Проверка тестов не пройдена','fix-tests · #c28b','20 мин назад','red']].map(([id,type,title,meta,time,color])=>`<button class="inbox-card ${activeAttention===id?'active':''}" data-action="attention" data-value="${id}"><span class="meta"><span>${type}</span><span>${time}</span></span><h3>${title}</h3><p>${meta}</p><div style="margin-top:13px">${badge(id==='failure'?'Остановлен':'Нужен человек',color)}</div></button>`).join('')}</div><div class="panel panel-pad">${attentionDetail()}</div></div><p class="inline-note">Это три разных состояния. Решение продолжает ожидающий шаг; предложение меняет конфигурацию; ошибка требует разбора причины.</p>`;}
function attentionDetail(){if(activeAttention==='proposal')return `<div class="detail-head">${badge('Предложение агента','orange')}<h3>Проверить правку конфигурации</h3><p>Агент предложил изменение файла .burnex/pipelines/self-improve.yml.</p></div><div class="code">  budget:<br><span style="color:var(--red)">−   cost: 3</span><br><span style="color:var(--green)">+   cost: 5</span></div><p class="inline-note">Предложение не применено. Здесь проверяется diff конфигурации, а не результат исходного кода.</p><div class="action-row">${button('Принять правку','simulate','Принятие предложения показано в макете. Файл не изменён.','primary')}${button('Отклонить','simulate','Отклонение показано в макете. Предложение в burnex не изменено.')}</div>`;
if(activeAttention==='failure')return `<div class="detail-head">${badge('Ошибка','red')}<h3>Тесты завершились с ошибкой</h3><p>fix-tests · #c28b · verify / tests</p></div><div class="code">npm test<br>AssertionError: expected status to equal success<br>Exit code: 1</div><p class="inline-note">Проверьте вывод шага, прежде чем возобновлять прогон.</p><div class="action-row">${button('Открыть прогон','run','2','primary')}${button('Показать Resume','simulate','В продукте Resume возобновляет прогон. В макете ничего не запущено.')}</div>`;
return `<div class="detail-head">${badge('Решение человека','orange')}<h3>Можно продолжить работу?</h3><p>Сценарий остановился на шаге review / decision и ждёт вашего ответа.</p></div><div class="detail-facts"><div><span>Сценарий</span><strong>review-change</strong></div><div><span>Прогон</span><strong>#b72a</strong></div><div><span>Ожидание</span><strong>8 минут</strong></div></div><div class="code">Изменения готовы к проверке.<br>Посмотрите результат и выберите исход шага.</div><p class="inline-note">В рабочем UI варианты ответа берутся из определения ожидающего шага. Здесь показан пример.</p><div class="action-row">${button('Открыть контекст','run','1')}${button('Продолжить','simulate','Ответ показан в макете. Реальный прогон по-прежнему ждёт решения.','primary')}${button('Отклонить…','reject')}</div>`;}
function catalog(){return `${heading('Сценарии работы','Сценарий (pipeline) — план действий. Каждый запуск создаёт отдельный прогон.')}<div class="scenario-grid">${scenarios.map(s=>`<article class="panel scenario-card ${s.featured?'featured':''}"><span class="scenario-icon">${s.icon}</span><h3>${s.name}</h3><p>${s.text}</p><div style="margin-top:18px"><span class="mono muted">${s.id}</span></div><div class="card-footer"><span class="small muted">${s.featured?'1 активный прогон':'Демо-сценарий'}</span>${button('Открыть →','scenario',s.id)}</div></article>`).join('')}</div><div class="section-title"><h3>Последние прогоны</h3>${button('Вся история →','navigate','runs','text-button')}</div>${runRows()}<p class="inline-note">Карточки демонстрируют подачу каталога. Наличие этих сценариев в вашем работающем демоне не проверялось.</p>`;}
function capabilityMap(){return `<div class="map-intro"><span class="eyebrow">РАЗРАБОТКА С ИИ-АГЕНТАМИ</span><h2>Вы задаёте процесс.<br>Burnex выполняет и проверяет.</h2><p>От очереди задач до управляемого прогона — с явными шагами, ограничениями и участием человека там, где это нужно.</p></div><div class="map-grid">${[['01','Подготовить работу','Что нужно сделать и каким способом.','plan','Очередь задач','catalog','Сценарии работы','schedule','Расписание'],['02','Следить за выполнением','Что происходит сейчас и где нужен ответ.','runs','Текущие прогоны','attention','Решения и предложения','usage','Расходы и токены'],['03','Настроить исполнение','Кто работает и какие ресурсы доступны.','settings','Агенты и модели','secrets','Секреты и доступ','system','Состояние системы']].map(([n,title,desc,...links])=>`<article class="panel map-card"><span class="map-number">${n} /</span><h3>${title}</h3><p>${desc}</p><div class="map-links">${[0,2,4].map(i=>button(`${links[i+1]} <span>↗</span>`,'navigate',links[i])).join('')}</div></article>`).join('')}</div><div class="utility-grid"><div class="panel utility-card"><div><h3>Расширить burnex</h3><p>Пакеты, виджеты и навигация под ваш процесс.</p></div>${button('Возможности →','navigate','extensions')}</div><div class="panel utility-card"><div><h3>Уже есть работа</h3><p>1 прогон выполняется · 1 ждёт ответа.</p></div>${button('К прогону →','run','0')}</div></div>`;}
function settings(){return `${heading('Агенты и окружение','Кто выполняет работу, чем пользуется и в каких пределах.')}<div class="settings-grid">${[['Агенты и модели','Модель по умолчанию, бэкенды, уровни и политика выбора.','agents'],['Секреты','Имена и доступность секретов. Значения не показываются.','secrets'],['Состояние системы','Версия, демон, автозапуск и состояние бэкендов.','system'],['Расписание','Когда запускаются сценарии. Просмотр настроек.','schedule']].map(([t,d,k])=>`<button class="panel setting-card" data-action="resource" data-value="${k}"><h3>${t} ↗</h3><p>${d}</p></button>`).join('')}</div>`;}
function extensions(){return `${heading('Расширения','Дополнительные возможности и устройство самой витрины.')}<div class="settings-grid">${[['Пакеты','Состав проекта и домашнего слоя, ресурсы и ошибки подключения.','packages'],['Виджеты','Каталог компонентов и установленные виджеты проектов.','widgets'],['Маршруты','Адреса, цели экранов и положение пунктов в меню.','routes'],['Хранилище прогонов','Предпросмотр очистки файлов и истории расходов.','cleanup']].map(([t,d,k])=>`<button class="panel setting-card" data-action="resource" data-value="${k}"><h3>${t} ↗</h3><p>${d}</p></button>`).join('')}</div>`;}
function usage(){return `${heading('Расходы на работу','Демонстрационный отчёт за сегодня.')}<div class="metrics">${[['Всего','$2.48'],['Токены','124k'],['Прогоны','3'],['Источник цены','Каталог']].map(([l,v])=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel">${[['self-improve','$0.84'],['review-change','$0.63'],['fix-tests','$1.01']].map(([n,v],i)=>`<button class="task-row" data-action="run" data-value="${i}"><span class="row-body"><strong>${n}</strong><p>Стоимость конкретного прогона →</p></span><strong>${v}</strong></button>`).join('')}</div><p class="inline-note">В продукте источник стоимости и неполные данные остаются видимыми. Оценка по каталогу не выдаётся за точное списание.</p>`;}
function schedule(){return `${heading('Расписание сценариев','Просмотр расписаний. Изменения задаются в документе пайплайна.')}<div class="panel"><div class="task-row"><span class="row-body"><strong>self-improve</strong><p>0 9 * * 1-5 · Asia/Nicosia · пример расписания</p></span>${badge('По будням')}${button('О сценарии','scenario','self-improve')}</div></div><p class="inline-note">Этот макет не добавляет редактор расписаний: текущий экран burnex предназначен для просмотра.</p>`;}
function bodyContent(){switch(section){case 'overview':return overview();case 'tasks':case 'plan':return tasksContent();case 'attention':case 'review':return inbox();case 'execute':case 'catalog':case 'scenarios':return catalog();case 'runs':return heading('Прогоны','Конкретные запуски сценариев: состояние, шаги и результат.')+metrics()+runRows();case 'settings':return settings()+`<div class="action-row">${button('Расходы и токены','navigate','usage')}${button('Хранилище прогонов','resource','cleanup')}${button('Расширения','navigate','extensions')}</div>`;case 'extensions':return extensions();case 'usage':return usage();case 'schedule':return schedule();case 'map':return capabilityMap();case 'secrets':case 'system':return resourceContent(section);default:return overview();}}
function render(){
const aliases = [{tasks:'plan', attention:'review', catalog:'execute', scenarios:'execute'}, {plan:'tasks', review:'attention', catalog:'scenarios', execute:'scenarios'}, {plan:'tasks', attention:'review'}, {plan:'tasks', review:'attention', scenarios:'catalog', execute:'catalog'}, {plan:'tasks', review:'attention'}];
section=aliases[variant-1][section]||section;
const c=concepts[variant-1];$('#concept-tabs').innerHTML=concepts.map((item,i)=>`<button class="concept-tab" data-action="variant" data-value="${i+1}" aria-current="${variant===i+1}"><span class="concept-num">0${i+1}</span><span><strong>${item.name}</strong><small>${item.sub}</small></span></button>`).join('');$('#concept-label').textContent=`КОНЦЕПЦИЯ 0${variant} / ${variant===1?'РЕКОМЕНДУЕМЫЙ СТАРТ':'АЛЬТЕРНАТИВНАЯ МОДЕЛЬ'}`;$('#concept-title').textContent=c.title;$('#concept-description').textContent=c.description;$('#concept-hypothesis').textContent=c.hypothesis;
let inner='';if(variant===1)inner=`<div class="shell">${sideNav([['overview','◫'],['plan','☷'],['execute','▷'],['review','◇'],['settings','⚙']],'Путь от намерения к результату')}<section class="content">${bodyContent()}</section></div>`;
if(variant===2)inner=topNav(['attention','runs','tasks','scenarios','settings'])+`<section class="content">${bodyContent()}</section>`;
if(variant===3)inner=`<div class="board-layout">${sideNav([['tasks','▤'],['runs','▷'],['review','◇'],['usage','◴']],'Контекст выбранного проекта')}<section class="board-content">${bodyContent()}</section></div>`;
if(variant===4)inner=topNav(['catalog','runs','tasks','attention','schedule','settings'])+`<section class="content">${bodyContent()}</section>`;
if(variant===5)inner=topNav(['map','tasks','runs','attention','extensions'])+`<section class="content">${bodyContent()}</section>`;
$('#prototype').innerHTML=appTop()+inner;}
function modal(content){$('#dialog-content').innerHTML=content;if(!$('#dialog').open)$('#dialog').showModal();}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function showRun(index){const r=runs[Number(index)]||runs[0];modal(`<div class="breadcrumb">Прогоны / ${r.scenario} / ${r.id}</div><h2>${r.name}</h2><p class="dialog-copy">Конкретное выполнение сценария <strong>${r.scenario}</strong>. Это демонстрационные данные.</p>${badge(r.status,r.color)}<div class="steps"><div class="step">✓ Подготовка<small>Завершена</small></div><div class="step ${index==='0'?'current':''}">Реализация<small>${index==='0'?'Выполняется':'Завершена'}</small></div><div class="step ${index!=='0'?'current':''}">Проверка<small>${index==='0'?'Ожидает':r.status}</small></div></div><div class="detail-facts"><div><span>Прогон</span><strong>${r.id}</strong></div><div><span>Сценарий</span><strong>${r.scenario}</strong></div><div><span>Состояние</span><strong>${r.status}</strong></div></div><div class="code">${index==='0'?'implement · агент выполняет текущий шаг\nПроверка результата ещё не запускалась.':index==='1'?'review / decision\nОжидается решение человека.':'verify / tests\nExit code: 1\nAssertionError: expected status to equal success'}</div><div class="action-row">${button('О сценарии','scenario',r.scenario)}${index==='1'?button('Перейти к решению','openattention','decision','primary'):index==='2'?button('Разобрать ошибку','openattention','failure','primary'):button('Закрыть','close','','primary')}</div>`);}
function showTask(id){const t=tasks.find(t=>t.id===id)||tasks[0];modal(`<div class="breadcrumb">Задачи / ${t.id}</div><h2>${t.title}</h2><p class="dialog-copy">${t.description}</p>${badge(t.status,t.color)}<div class="dialog-section"><h3>Что происходит с задачей</h3><p>${t.column===1?'Задачу выполняет self-improve. Владелец и ссылка на прогон показываются только при явной связи в данных.':t.column===2?'Задача завершена. Ссылка на результат доступна, если сохранилась связь с прогоном.':'Задача находится в очереди. Для выполнения выберите сценарий и создайте прогон.'}</p></div><div class="panel"><div class="task-row"><span class="row-body"><strong>${t.run?t.meta:'Связанного прогона пока нет'}</strong><p>${t.column===2?'Завершён · демонстрационный пример':t.run?'Шаг implement · выполнение':'Изменение статуса само по себе не запускает агента'}</p></span>${t.column===1?button('Открыть','run','0'):t.column===0?button('Выбрать сценарий','launch','','primary'):badge('Успешно','green')}</div></div><p class="inline-note">Если связь с прогоном недоступна, интерфейс не подставляет похожий по названию запуск.</p>`);}
function showScenario(id){const s=scenarios.find(s=>s.id===id)||scenarios[0];modal(`<div class="breadcrumb">Сценарии / ${s.id}</div><h2>${s.name}</h2><p class="dialog-copy">${s.text}</p><div class="code">${s.meta}</div><div class="detail-facts"><div><span>Определение</span><strong>Пайплайн</strong></div><div><span>Исполнитель</span><strong>Из политики агентов</strong></div><div><span>Запуск</span><strong>Отдельный прогон</strong></div></div><div class="section-title"><h3>Связанный прогон</h3></div><div class="panel"><button class="task-row" data-action="run" data-value="${scenarios.indexOf(s)===1?2:scenarios.indexOf(s)===2?1:0}"><span class="row-body"><strong>${s.id}</strong><p>Открыть состояние и шаги →</p></span>${badge(s.id==='self-improve'?'Выполняется':s.id==='fix-tests'?'Ошибка':'Ждёт ответа',s.id==='self-improve'?'green':'orange')}</button></div><div class="action-row">${button('Подготовить запуск','launch',s.id,'primary')}${button('Агенты и политика','resource','agents')}</div><p class="inline-note">Группировка прогонов — по проекту и файлу пайплайна. Название не является уникальным идентификатором.</p>`);}
function launch(id){modal(`<h2>Новый прогон</h2><p class="dialog-copy">Сценарий задаёт шаги. Прогон выполняет их с выбранными параметрами.</p><div class="form-grid"><label>Проект<input value="burnex" readonly></label><label>Сценарий<select id="launch-scenario">${scenarios.map(s=>`<option value="${s.id}" ${id===s.id?'selected':''}>${s.name} · ${s.id}</option>`).join('')}</select></label><label>Входные параметры<input placeholder="topic=навигация"></label><label>Агент<select><option>Из настроек сценария</option><option>codex · пример</option></select></label></div><label class="check-label"><input type="checkbox"> Shadow — внешние действия записываются, а не выполняются</label><details class="dialog-section"><summary class="small">Переменные окружения</summary><p>Дополнительные параметры конкретного запуска.</p><input class="search" aria-label="Переменные окружения" placeholder="KEY=VALUE"></details><div class="callout"><div><strong>Предпросмотр формы</strong><p>Кнопка ниже только показывает итог. Этот макет не обращается к API.</p></div></div><div class="action-row">${button('Показать итог запуска','launchpreview','','primary')}${button('Отмена','close')}</div>`);}
const resources={agents:['Агенты и модели','Четыре вкладки существующего экрана: по умолчанию, бэкенды, уровни и политика.','/agents/:tab?'],secrets:['Секреты','Имена секретов и статус провайдеров. Значения не раскрываются.','/secrets'],system:['Состояние системы','Версия установки, демон, автозапуск и состояние бэкендов. Действия обновления в этом макете отсутствуют.','/system'],schedule:['Расписание','Только просмотр. Редактирование остаётся в документе пайплайна.','/schedule'],packages:['Пакеты','Состав проекта и домашнего слоя: подключённые ресурсы и ошибки.','/packages'],widgets:['Виджеты','Каталог компонентов и виджеты, подключённые проектами.','/widgets'],routes:['Маршруты','Адреса, цели и расположение пунктов меню. Пользовательские маршруты сохраняются.','/routes'],cleanup:['Хранилище прогонов','Предпросмотр очистки файлов прогонов и истории расхода. Удаление в макете недоступно.','/cleanup']};
function resourceContent(key){const r=resources[key];return `${heading(r[0],r[1])}<div class="panel panel-pad"><span class="eyebrow">СУЩЕСТВУЮЩИЙ РАЗДЕЛ</span><h3>${r[0]}</h3><p class="dialog-copy">Варианты меняют точку входа и объяснение, сохраняя возможности этого экрана.</p><span class="link-chip">${r[2]}</span></div>`;}
function compare(){modal(`<h2>Какую модель выбрать?</h2><p class="dialog-copy">Критерий — сможет ли человек объяснить возможности burnex и найти нужное действие. Это проектные гипотезы, а не результаты пользовательского теста.</p><table class="compare-table"><thead><tr><th>Модель</th><th>Главный вопрос</th><th>Сильнее всего помогает</th><th>Компромисс</th></tr></thead><tbody>${[['По этапам','Что делать дальше?','Понять процесс целиком','Настройки глубже'],['Центр внимания','Где нужен я?','Контролировать много прогонов','Слабее знакомит с продуктом'],['Вокруг задачи','Что с моей задачей?','Сохранить контекст работы','Нужна явная связь с прогоном'],['Вокруг сценария','Что поручить движку?','Понять повторяемую автоматизацию','Задачи менее заметны'],['Карта возможностей','Что здесь возможно?','Обнаружить функции','Больше чтения на главной']].map((row,i)=>`<tr class="${i===0?'recommended':''}">${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="dialog-section"><h3>Предлагаю начать с №1</h3><p>Он даёт понятную структуру повседневной работы. Из №2 стоит взять заметный вход в ожидания человека, а из №5 — короткие объяснения возможностей.</p></div><div class="dialog-section"><h3>Проверка перед выбором</h3><p>Дать новым пользователям одинаковые задания: найти очередь, выбрать сценарий, открыть прогон, найти ожидание ответа и расходы. Сравнить первый выбор раздела, неверные переходы, время и объяснение разницы «сценарий / прогон».</p></div><div class="action-row">${concepts.map((c,i)=>button(`0${i+1} · ${c.name}`,'choose',String(i+1))).join('')}</div>`);}
function rationale(){const c=concepts[variant-1];modal(`<h2>0${variant}. ${c.name}</h2><p class="dialog-copy">${c.hypothesis}</p>${[['Для кого',c.audience],['Почему понятнее',c.benefit],['Путь пользователя',c.route],['Компромисс',c.risk],['Без изменения backend',c.backend],['Как проверить',c.test]].map(([title,copy])=>`<div class="dialog-section"><h3>${title}</h3><p>${copy}</p></div>`).join('')}<div class="action-row">${button('Сравнить все пять','compare','','primary')}</div>`);}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const {action,value}=target.dataset;
switch(action){case 'variant':case 'choose':if($('#dialog').open)$('#dialog').close();variant=Number(value);section=initialSections[variant-1];query='';location.hash=String(variant);render();break;
case 'navigate':section=value;query='';render();break;case 'close':$('#dialog').close();break;case 'compare':compare();break;case 'rationale':rationale();break;case 'attention':activeAttention=value;render();break;case 'openattention':$('#dialog').close();section='attention';activeAttention=value;render();break;case 'taskview':taskView=value;render();break;case 'task':showTask(value);break;case 'run':showRun(value);break;case 'scenario':showScenario(value);break;case 'launch':launch(value);break;case 'simulate':notify(value);break;case 'resource':modal(resourceContent(value));break;
case 'launchpreview':{const label=$('#launch-scenario').selectedOptions[0].textContent;modal(`<h2>Запуск подготовлен в макете</h2><p class="dialog-copy">${escapeHtml(label)}</p><div class="panel panel-pad"><h3>В рабочем интерфейсе здесь появится новый прогон</h3><p class="dialog-copy">Проект → сценарий → параметры → отдельное выполнение. Ни один запрос к демону не отправлен.</p></div><div class="action-row">${button('Посмотреть пример прогона','run','0','primary')}${button('Закрыть','close')}</div>`);break;}
case 'reject':modal(`<h2>Отклонить результат</h2><p class="dialog-copy">Причина помогает понять, что необходимо исправить.</p><label class="small">Причина<input id="reject-reason" class="search" style="display:block;width:100%;margin-top:10px" placeholder="Что нужно изменить?"></label><div class="action-row">${button('Показать отклонение','rejectpreview','','primary')}${button('Отмена','close')}</div>`);break;
case 'rejectpreview':if(!$('#reject-reason').value.trim()){$('#reject-reason').focus();notify('Укажите причину отклонения.');}else{notify('Отклонение показано в макете. Реальный прогон не изменён.');$('#dialog').close();}break;
case 'addtask':modal(`<h2>Новая задача</h2><p class="dialog-copy">Пример входа в существующее добавление пункта очереди.</p><label class="small">Что нужно сделать?<input id="new-task-title" class="search" style="display:block;width:100%;margin-top:10px" placeholder="Например, улучшить сообщения об ошибках"></label><div class="action-row">${button('Добавить в демо-очередь','addtaskpreview','','primary')}${button('Отмена','close')}</div>`);break;
case 'addtaskpreview':{const title=$('#new-task-title').value.trim();if(!title){$('#new-task-title').focus();notify('Напишите название задачи.');break;}tasks.push({id:`DEMO-${tasks.length+1}`,title:escapeHtml(title),status:'В очереди',column:0,description:'Новая задача в памяти макета.',meta:'Не сохранена в burnex',color:'',run:false});$('#dialog').close();section='tasks';query='';render();notify('Добавлено только в макет. При перезагрузке исчезнет.');break;}
}});
document.addEventListener('input',event=>{if(event.target.id==='task-search'){query=event.target.value;$('#task-results').innerHTML=taskResults(tasks.filter(t=>(t.title+' '+t.id).toLowerCase().includes(query.toLowerCase())));}});
window.addEventListener('hashchange',()=>{const next=Math.min(5,Math.max(1,Number(location.hash.slice(1))||1));if(next!==variant){variant=next;section=initialSections[variant-1];query='';render();}});
section=initialSections[variant-1];render();
